from typing import List
from collections import defaultdict, deque

def numBusesToDestination(routes: List[List[int]], S: int, T: int) -> int:
    if S == T:
        return 0

    # Create a graph where each bus stop is a node and each bus route is a connection
    stop_to_routes = defaultdict(list)
    for i, route in enumerate(routes):
        for stop in route:
            stop_to_routes[stop].append(i)

    # Use BFS to find the shortest path in terms of bus routes
    queue = deque([(S, 0)])  # (current stop, number of buses taken)
    visited_stops = set([S])
    visited_routes = set()

    while queue:
        current_stop, buses_taken = queue.popleft()

        for route_index in stop_to_routes[current_stop]:
            if route_index not in visited_routes:
                visited_routes.add(route_index)
                for next_stop in routes[route_index]:
                    if next_stop == T:
                        return buses_taken + 1
                    if next_stop not in visited_stops:
                        visited_stops.add(next_stop)
                        queue.append((next_stop, buses_taken + 1))

    return -1
